'use strict';
const fs=require('fs'),path=require('path'),crypto=require('crypto'),assert=require('assert');const {pathToFileURL}=require('url');
const root=process.cwd(),out=path.join(root,'.cvf/runtime/cvf-expense-layout-local-review-20261010'),web=path.join(root,'EXTENSIONS/CVF_v1.6_AGENT_PLATFORM/cvf-web'),source=path.join(web,'src/expenses/ExpenseList.tsx');
const digest=()=>crypto.createHash('sha256').update(fs.readFileSync(source)).digest('hex'),start=digest();
const longLabel='LocalChoice0123456789'.repeat(6);const fixture=[{id:'L-FEB',date:'2026-02-28',label:'Other month',amount:70000},{id:'L-M2',date:'2026-03-30',label:longLabel,amount:246810},{id:'L-M1',date:'2026-03-01',label:'Own independent review',amount:135790},{id:'L-BAD',date:'05/03/2026',label:'Invalid',amount:99999}];
const fits=(b,a)=>b.left>=a.left-1&&b.right<=a.right+1&&b.top>=a.top-1&&b.bottom<=a.bottom+1;
const requireContained=s=>{assert(fits(s.table,s.section),'table outside section inner bounds');for(const c of s.cells){assert(fits(c.rect,s.section),'cell outside section inner bounds');for(const line of c.lines)assert(fits(line,c.inner),'text outside cell inner bounds')}assert(s.docOverflow<=0&&s.sectionOverflow<=1,'horizontal overflow');};
(async()=>{
 fs.mkdirSync(out,{recursive:true});const entry=path.join(out,'own-entry.tsx');fs.writeFileSync(entry,`import React from 'react';import {createRoot} from 'react-dom/client';import {ExpenseList} from ${JSON.stringify(path.relative(out,source).replace(/\\/g,'/'))};createRoot(document.getElementById('root')).render(React.createElement(ExpenseList,{expenses:${JSON.stringify(fixture)}}));`);
 const vite=await import(pathToFileURL(path.join(web,'node_modules/vite/dist/node/index.js')).href);
 const build=await vite.build({configFile:false,envFile:false,root:out,mode:'production',logLevel:'silent',define:{'process.env.NODE_ENV':'"production"'},resolve:{alias:[{find:'react-dom',replacement:path.join(web,'node_modules/react-dom').replace(/\\/g,'/')},{find:'react',replacement:path.join(web,'node_modules/react').replace(/\\/g,'/')}]},oxc:{jsx:{runtime:'automatic'}},build:{write:false,minify:true,sourcemap:false,emptyOutDir:false,lib:{entry,formats:['iife'],name:'LocalLayout'}}});
 const chunks=(Array.isArray(build)?build:[build]).flatMap(x=>x.output);assert.equal(chunks.length,1);const file=path.join(out,'own-330.html');fs.writeFileSync(file,`<!doctype html><meta charset="utf-8"><style>:root{color-scheme:dark;--cvf-bg-page:#111218;--cvf-surface:#1c1d27;--cvf-text-primary:#f4f7fb;--cvf-text-secondary:#a3adc2;--cvf-text-muted:#6f7890;--cvf-border:rgba(255,255,255,.08);--cvf-border-strong:rgba(255,255,255,.14);--cvf-warning:#f59e0b;--cvf-accent:#5b5cf6}body{margin:0;padding:16px;font:16px system-ui;background:var(--cvf-bg-page)}</style><div id="root"></div><script>${chunks[0].code.replace(/<\/script/gi,'<\\/script')}</script>`);
 const {chromium}=require(path.join(web,'node_modules/@playwright/test'));const browser=await chromium.launch({headless:true});let report;
 try{const ctx=await browser.newContext({viewport:{width:330,height:844}}),page=await ctx.newPage();page.setDefaultTimeout(15000);const external=[],errors=[];await ctx.route('**/*',r=>r.request().url().startsWith('file:')?r.continue():r.abort());page.on('request',r=>{if(!r.url().startsWith('file:'))external.push(r.url())});page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});await page.goto(pathToFileURL(file).href);await page.waitForSelector('[data-expense-id="L-M2"]');await page.locator('input[type=month]').fill('2026-03');await page.waitForFunction(()=>document.querySelectorAll('[data-expense-id]').length===2);
 const measure=()=>page.evaluate(()=>{const rect=el=>{const r=el.getBoundingClientRect();return {left:r.left,right:r.right,top:r.top,bottom:r.bottom}};const inner=el=>{const r=rect(el),c=getComputedStyle(el);return {left:r.left+parseFloat(c.borderLeftWidth||0)+parseFloat(c.paddingLeft||0),right:r.right-parseFloat(c.borderRightWidth||0)-parseFloat(c.paddingRight||0),top:r.top+parseFloat(c.borderTopWidth||0)+parseFloat(c.paddingTop||0),bottom:r.bottom-parseFloat(c.borderBottomWidth||0)-parseFloat(c.paddingBottom||0)}};const section=document.querySelector('section'),table=document.querySelector('table');return {section:inner(section),table:rect(table),docOverflow:document.documentElement.scrollWidth-innerWidth,sectionOverflow:section.scrollWidth-section.clientWidth,ids:[...document.querySelectorAll('[data-expense-id]')].map(x=>x.dataset.expenseId),inputHeight:document.querySelector('input').getBoundingClientRect().height,cells:[...table.querySelectorAll('th,td')].map(c=>{const range=document.createRange();range.selectNodeContents(c);return {text:c.textContent,rect:rect(c),inner:inner(c),lines:[...range.getClientRects()].map(r=>({left:r.left,right:r.right,top:r.top,bottom:r.bottom}))}})}});
 const positive=await measure();requireContained(positive);assert.deepEqual(positive.ids,['L-M2','L-M1']);assert.equal(positive.inputHeight,44);assert.deepEqual(positive.cells.map(c=>c.text),['Ngày','Nội dung','Số tiền','2026-03-30',longLabel,'246810','2026-03-01','Own independent review','135790']);await page.screenshot({path:path.join(out,'own-330.png'),fullPage:true});
 await page.evaluate(()=>{document.querySelector('[data-expense-id="L-M2"] td:nth-child(2)').style.whiteSpace='nowrap'});const negative=await measure();let rejected=false,reason=null;try{requireContained(negative)}catch(e){assert.equal(e.name,'AssertionError');rejected=true;reason=e.message}assert(rejected,'negative must be rejected');await page.evaluate(()=>{document.querySelector('[data-expense-id="L-M2"] td:nth-child(2)').style.removeProperty('white-space')});const restored=await measure();requireContained(restored);assert.deepEqual(restored.ids,['L-M2','L-M1']);assert.equal(digest(),start);assert.equal(external.length,0);assert.equal(errors.length,0);
 report={status:'PASS',viewport:{width:330,height:844},sourceSha256:start,oracle:'Own literal fixture/IDs/complete cell text and inner-box bounds; no worker test import; source exposure disclosed',positive,negative:{control:'DOM-only label white-space nowrap; no source mutation',rejectedByAssertion:rejected,reason,table:negative.table,section:negative.section},restored:'PASS',externalRequests:external.length,pageErrors:errors.length,browserVersion:browser.version()};await ctx.close();
 }finally{await browser.close()}
 fs.writeFileSync(path.join(out,'probe-results.json'),JSON.stringify(report,null,2)+'\n');process.stdout.write(JSON.stringify({status:report.status,ids:report.positive.ids,inputHeight:report.positive.inputHeight,negative:report.negative})+'\n');
})().catch(e=>{process.stderr.write(e.stack+'\n');process.exitCode=1});
